<div class="stack"><div class="hero-actions"><div><h1>Gestione categorie</h1><p class="muted">CRUD categorie per il frontend pubblico.</p></div><a class="btn" href="<?php echo e(url('/admin/categories/create')); ?>">Nuova categoria</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Categoria</th><th>Descrizione</th><th>Offerte</th><th>Azioni</th></tr></thead><tbody><?php foreach ($items as $category): ?><tr><td><?php echo e($category['icon'] . ' ' . $category['name']); ?></td><td><small><?php echo e($category['description']); ?></small></td><td><?php echo e((string) $category['offer_count']); ?></td><td><div class="table-actions"><a class="btn btn-secondary" href="<?php echo e(url('/admin/categories/' . $category['id'] . '/edit')); ?>">Modifica</a><form action="<?php echo e(url('/admin/categories/' . $category['id'] . '/delete')); ?>" method="post"><?php echo csrf_field(); ?><button class="btn btn-danger" type="submit">Elimina</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div>
